//! Process-launch helper shared by `terminal` and `user`.
//!
//! Not a tool module: it does not export descriptors and has no conf key.
//! Stdout of the child is streamed to the parent stdout (not through Logger).

use std::io::{Read, Write};
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

/// Run `cmd` in `cwd` with a timeout, streaming output to stdout.
///
/// Empty captured output becomes `(command finished without output)`.
pub fn run_observed_command(cmd: &str, cwd: &Path, timeout_secs: u64) -> Result<String, String> {
    let mut command = shell_command(cmd);
    command
        .current_dir(cwd)
        .env("PYTHONUNBUFFERED", "1")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    let mut child = command
        .spawn()
        .map_err(|e| format!("cannot spawn '{cmd}': {e}"))?;

    let chunks = Arc::new(Mutex::new(Vec::<u8>::new()));
    let mut pumps = Vec::new();
    if let Some(stdout) = child.stdout.take() {
        pumps.push(spawn_pump(stdout, chunks.clone()));
    }
    if let Some(stderr) = child.stderr.take() {
        pumps.push(spawn_pump(stderr, chunks.clone()));
    }

    let timeout = Duration::from_secs(timeout_secs);
    let start = Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) if start.elapsed() > timeout => {
                let _ = child.kill();
                let _ = child.wait();
                for t in pumps {
                    let _ = t.join();
                }
                return Err(format!(
                    "execution of the '{cmd}' exceed the limit (available limit is {timeout_secs}s)"
                ));
            }
            Ok(None) => thread::sleep(Duration::from_millis(20)),
            Err(e) => {
                let _ = child.kill();
                return Err(format!("wait failed for '{cmd}': {e}"));
            }
        }
    };
    for t in pumps {
        let _ = t.join();
    }
    let _ = status;
    let raw = chunks.lock().map(|g| g.clone()).unwrap_or_default();
    Ok(decode_command_output(&raw))
}

fn spawn_pump<R: Read + Send + 'static>(
    mut stream: R,
    chunks: Arc<Mutex<Vec<u8>>>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut buf = [0u8; 4096];
        loop {
            match stream.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    let data = &buf[..n];
                    if let Ok(mut g) = chunks.lock() {
                        g.extend_from_slice(data);
                    }
                    let _ = std::io::stdout().write_all(data);
                    let _ = std::io::stdout().flush();
                }
                Err(_) => break,
            }
        }
    })
}

fn shell_command(cmd: &str) -> Command {
    #[cfg(windows)]
    {
        let mut c = Command::new("cmd");
        c.args(["/C", cmd]);
        c
    }
    #[cfg(not(windows))]
    {
        let mut c = Command::new("sh");
        c.args(["-c", cmd]);
        c
    }
}

fn decode_command_output(raw: &[u8]) -> String {
    if raw.is_empty() {
        return "(command finished without output)".to_string();
    }
    if let Ok(s) = std::str::from_utf8(raw) {
        return s.to_string();
    }
    let oem = encoding_rs::IBM866.decode(raw);
    if !oem.2 {
        return oem.0.into_owned();
    }
    encoding_rs::WINDOWS_1251.decode(raw).0.into_owned()
}

//! Filesystem tool set (`tools.fs`): files/folders, search, and allow-list introspection.
//!
//! This module owns `available-dirs`, `available-file-extensions`, `available-files`,
//! `deprecated-dirs` and `deprecated-files`.
//! `write_file` creates parent directories; `create_file` does not and truncates
//! an existing file.

use std::fs;
use std::path::Path;
use std::sync::{Arc, Mutex};

use serde_json::{json, Map, Value};

use crate::{arg_str, CallKind, CallResult, ToolDescriptor};

mod access;
mod search;

pub use access::{abspath, Sandbox};

/// Filesystem tools bound to the allow-list this module owns.
pub struct FsModule {
    sandbox: Arc<Mutex<Sandbox>>,
}

impl FsModule {
    /// Wrap an existing allow-list.
    pub fn new(sandbox: Arc<Mutex<Sandbox>>) -> Self {
        Self { sandbox }
    }

    /// Build the fs module and the allow-list it owns.
    ///
    /// When `settings` is `None` there is no module and the allow-list is empty
    /// (still shared with `git` / `user`).
    pub fn build(settings: Option<&conf::FsSettings>) -> (Option<Self>, Arc<Mutex<Sandbox>>) {
        match settings {
            Some(fs) => {
                let module = Self::new(Arc::new(Mutex::new(Sandbox::from_fs(
                    &fs.available_dirs,
                    &fs.available_files,
                    &fs.available_file_extensions,
                    &fs.deprecated_dirs,
                    &fs.deprecated_files,
                ))));
                let sandbox = module.sandbox.clone();
                (Some(module), sandbox)
            }
            None => (None, Arc::new(Mutex::new(Sandbox::empty()))),
        }
    }

    /// JSON Schema descriptors for the fs tools.
    pub fn descriptors() -> Vec<ToolDescriptor> {
        vec![
            desc("read_file", "Read the contents of a file.", json!({"type":"object","properties":{"path":{"type":"string"}},"required":["path"]})),
            desc("write_file", "Write a file.", json!({"type":"object","properties":{"path":{"type":"string"},"content":{"type":"string"}},"required":["path","content"]})),
            desc("create_file", "Create a file.", json!({"type":"object","properties":{"path":{"type":"string"}},"required":["path"]})),
            desc("remove_file", "Delete a file.", json!({"type":"object","properties":{"path":{"type":"string"}},"required":["path"]})),
            desc("move_file", "Move a file.", json!({"type":"object","properties":{"src":{"type":"string"},"dst":{"type":"string"}},"required":["src","dst"]})),
            desc("list_folder", "Return the contents of a directory to the given depth (depth >= 0, where 0 is root contents only).", json!({"type":"object","properties":{"path":{"type":"string"},"depth":{"type":"string"}},"required":["path","depth"]})),
            desc("create_folder", "Create a folder.", json!({"type":"object","properties":{"path":{"type":"string"}},"required":["path"]})),
            desc("remove_folder", "Delete a folder.", json!({"type":"object","properties":{"path":{"type":"string"}},"required":["path"]})),
            desc("move_folder", "Move a folder.", json!({"type":"object","properties":{"src":{"type":"string"},"dst":{"type":"string"}},"required":["src","dst"]})),
            desc("find_str", "Search for a string in files starting from the root directory.", json!({"type":"object","properties":{"root":{"type":"string"},"string":{"type":"string"}},"required":["root","string"]})),
            desc("find_str_by_regex", "Search for lines matching a regular expression starting from the root directory.", json!({"type":"object","properties":{"root":{"type":"string"},"regex":{"type":"string"}},"required":["root","regex"]})),
            desc("find_file_by_str", "Find files whose names contain the given string, starting from the root directory.", json!({"type":"object","properties":{"root":{"type":"string"},"string":{"type":"string"}},"required":["root","string"]})),
            desc("find_files_by_regex", "Find files whose names match the given regular expression, starting from the root directory.", json!({"type":"object","properties":{"root":{"type":"string"},"regex":{"type":"string"}},"required":["root","regex"]})),
            desc("list_available_file_extension", "List of available file extensions.", json!({})),
            desc("list_available_r_dir", "List of directories available for reading.", json!({})),
            desc("list_available_w_dir", "List of directories available for writing.", json!({})),
            desc("list_available_r_file", "List of files available for reading.", json!({})),
            desc("list_available_w_file", "List of files available for writing.", json!({})),
        ]
    }

    /// Dispatch a named fs tool.
    pub fn call(&self, name: &str, args: &Map<String, Value>) -> Result<CallResult, String> {
        match name {
            "read_file" => {
                let text = self.read_file(&arg_str(args, "path")?)?;
                Ok(CallResult {
                    output: text,
                    kind: CallKind::Read,
                })
            }
            "write_file" => {
                let text = self.write_file(&arg_str(args, "path")?, &arg_str(args, "content")?)?;
                Ok(CallResult {
                    output: text,
                    kind: CallKind::Write,
                })
            }
            "create_file" => Ok(CallResult::plain(
                self.create_file(&arg_str(args, "path")?)?,
            )),
            "remove_file" => Ok(CallResult::plain(
                self.remove_file(&arg_str(args, "path")?)?,
            )),
            "move_file" => Ok(CallResult::plain(
                self.move_file(&arg_str(args, "src")?, &arg_str(args, "dst")?)?,
            )),
            "list_folder" => Ok(CallResult::plain(
                self.list_folder(&arg_str(args, "path")?, &arg_str(args, "depth")?)?,
            )),
            "create_folder" => Ok(CallResult::plain(
                self.create_folder(&arg_str(args, "path")?)?,
            )),
            "remove_folder" => Ok(CallResult::plain(
                self.remove_folder(&arg_str(args, "path")?)?,
            )),
            "move_folder" => Ok(CallResult::plain(
                self.move_folder(&arg_str(args, "src")?, &arg_str(args, "dst")?)?,
            )),
            "find_str" => Ok(CallResult::plain(search::find_str(
                &self.sandbox,
                &arg_str(args, "root")?,
                &arg_str(args, "string")?,
            )?)),
            "find_str_by_regex" => Ok(CallResult::plain(search::find_str_by_regex(
                &self.sandbox,
                &arg_str(args, "root")?,
                &arg_str(args, "regex")?,
            )?)),
            "find_file_by_str" => Ok(CallResult::plain(search::find_file_by_str(
                &self.sandbox,
                &arg_str(args, "root")?,
                &arg_str(args, "string")?,
            )?)),
            "find_files_by_regex" => Ok(CallResult::plain(search::find_files_by_regex(
                &self.sandbox,
                &arg_str(args, "root")?,
                &arg_str(args, "regex")?,
            )?)),
            "list_available_file_extension" => Ok(CallResult::plain(self.list_extensions()?)),
            "list_available_r_dir" => Ok(CallResult::plain(self.list_paths(|sb| sb.r_dirs())?)),
            "list_available_w_dir" => Ok(CallResult::plain(self.list_paths(|sb| sb.w_dirs())?)),
            "list_available_r_file" => Ok(CallResult::plain(self.list_paths(|sb| sb.r_files())?)),
            "list_available_w_file" => Ok(CallResult::plain(self.list_paths(|sb| sb.w_files())?)),
            _ => Err(format!("tool '{name}' not available")),
        }
    }

    fn read_file(&self, path: &str) -> Result<String, String> {
        self.guard(path, 'r', true)
            .and_then(|_| fs::read_to_string(path).map_err(|e| e.to_string()))
            .map_err(|e| format!("cannot read file '{path}' → {e}"))
    }

    fn write_file(&self, path: &str, content: &str) -> Result<String, String> {
        (|| {
            self.guard(path, 'w', true)?;
            if let Some(parent) = Path::new(path).parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|e| e.to_string())?;
                }
            }
            fs::write(path, content).map_err(|e| e.to_string())?;
            Ok(format!("success: wrote {path}"))
        })()
        .map_err(|e: String| format!("cannot write file '{path}' → {e}"))
    }

    fn create_file(&self, path: &str) -> Result<String, String> {
        (|| {
            self.guard(path, 'w', true)?;
            fs::write(path, "").map_err(|e| e.to_string())?;
            Ok(format!("success: created {path}"))
        })()
        .map_err(|e: String| format!("cannot create file '{path}' → {e}"))
    }

    fn remove_file(&self, path: &str) -> Result<String, String> {
        (|| {
            self.guard(path, 'w', false)?;
            fs::remove_file(path).map_err(|e| e.to_string())?;
            Ok(format!("success: removed {path}"))
        })()
        .map_err(|e: String| format!("cannot remove file '{path}' → {e}"))
    }

    fn move_file(&self, src: &str, dst: &str) -> Result<String, String> {
        (|| {
            self.guard(src, 'w', true)?;
            self.guard(dst, 'w', true)?;
            fs::rename(src, dst).map_err(|e| e.to_string())?;
            Ok(format!("success: moved {src} to {dst}"))
        })()
        .map_err(|e: String| format!("cannot move file '{src}' to {dst} → {e}"))
    }

    fn list_folder(&self, path: &str, depth: &str) -> Result<String, String> {
        (|| {
            let depth: i32 = depth.parse().map_err(|e| format!("{e}"))?;
            let sb = self.sandbox.lock().map_err(|e| e.to_string())?;
            sb.check_access(path, 'r')?;
            Ok(walk_folder(path, depth, &sb).join("\n"))
        })()
        .map_err(|e: String| format!("cannot list folder '{path}' → {e}"))
    }

    fn create_folder(&self, path: &str) -> Result<String, String> {
        (|| {
            self.guard(path, 'w', false)?;
            fs::create_dir_all(path).map_err(|e| e.to_string())?;
            Ok(format!("success: created {path}"))
        })()
        .map_err(|e: String| format!("cannot create folder '{path}' → {e}"))
    }

    fn remove_folder(&self, path: &str) -> Result<String, String> {
        (|| {
            self.guard(path, 'w', false)?;
            fs::remove_dir_all(path).map_err(|e| e.to_string())?;
            Ok(format!("success: removed {path}"))
        })()
        .map_err(|e: String| format!("cannot remove folder '{path}' → {e}"))
    }

    fn move_folder(&self, src: &str, dst: &str) -> Result<String, String> {
        (|| {
            self.guard(src, 'w', false)?;
            self.guard(dst, 'w', false)?;
            fs::rename(src, dst).map_err(|e| e.to_string())?;
            Ok(format!("success: moved {src} to {dst}"))
        })()
        .map_err(|e: String| format!("cannot move folder '{src}' to '{dst}' → {e}"))
    }

    fn guard(&self, path: &str, mode: char, check_ext: bool) -> Result<(), String> {
        let sb = self.sandbox.lock().map_err(|e| e.to_string())?;
        sb.check_access(path, mode)?;
        if check_ext {
            sb.check_extensions(path, mode)?;
        }
        Ok(())
    }

    fn list_extensions(&self) -> Result<String, String> {
        let sb = self.sandbox.lock().map_err(|e| e.to_string())?;
        if sb.extensions().is_empty() {
            Ok("available: all".to_string())
        } else {
            Ok(format!("available: {:?}", sb.extensions()))
        }
    }

    fn list_paths(&self, pick: fn(&Sandbox) -> &[String]) -> Result<String, String> {
        let sb = self.sandbox.lock().map_err(|e| e.to_string())?;
        Ok(format!("available: {:?}", pick(&sb)))
    }
}

fn walk_folder(path: &str, depth: i32, sandbox: &Sandbox) -> Vec<String> {
    let mut result = Vec::new();
    if depth <= 0 {
        return result;
    }
    let Ok(entries) = fs::read_dir(path) else {
        return result;
    };
    let mut names: Vec<_> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    names.sort();
    let mut dirs = Vec::new();
    let mut files = Vec::new();
    for full in names {
        let s = full.to_string_lossy();
        if sandbox.is_deprecated(&s) {
            continue;
        }
        if full.is_dir() {
            dirs.push(full);
        } else {
            files.push(full);
        }
    }
    for folder in dirs {
        result.push(folder.to_string_lossy().into_owned());
        result.extend(walk_folder(&folder.to_string_lossy(), depth - 1, sandbox));
    }
    for file in files {
        result.push(file.to_string_lossy().into_owned());
    }
    result
}

fn desc(name: &str, description: &str, parameters: Value) -> ToolDescriptor {
    ToolDescriptor {
        name: name.to_string(),
        description: description.to_string(),
        parameters,
    }
}

//! Allow-lists and denylists for directories, exact files and extensions, owned by `fs`.
//!
//! Directories are matched by `abspath` prefix; available-files by exact
//! `abspath`. A `w:` grant always implies `r:`. Empty extension list means any
//! extension is allowed. The lists are mutated at runtime by `request_*`.
//!
//! `deprecated-dirs` / `deprecated-files` are checked before the allow-list.
//! Deprecated directories match by path-component prefix (`target` does not
//! block `target2`); deprecated files match exact `abspath`. Windows is case-insensitive.

use std::path::{Component, Path, PathBuf};

/// Allow-lists for directories, exact files and extensions.
#[derive(Debug, Clone, Default)]
pub struct Sandbox {
    r_dirs: Vec<String>,
    w_dirs: Vec<String>,
    r_files: Vec<String>,
    w_files: Vec<String>,
    extensions: Vec<String>,
    deprecated_dirs: Vec<String>,
    deprecated_files: Vec<String>,
}

impl Sandbox {
    /// Build from `tools.fs` entries. Unknown / unprefixed items are skipped.
    pub fn from_fs(
        available_dirs: &[String],
        available_files: &[String],
        extensions: &[String],
        deprecated_dirs: &[String],
        deprecated_files: &[String],
    ) -> Self {
        let mut sb = Self {
            extensions: extensions.to_vec(),
            deprecated_dirs: deprecated_dirs.to_vec(),
            deprecated_files: deprecated_files.to_vec(),
            ..Self::default()
        };
        split_prefixed(available_dirs, &mut sb.r_dirs, &mut sb.w_dirs);
        split_prefixed(available_files, &mut sb.r_files, &mut sb.w_files);
        sb
    }

    /// Empty allow-list (no `fs` module in conf).
    pub fn empty() -> Self {
        Self::default()
    }

    /// Read-directory allow-list as stored (including `w` dirs).
    pub fn r_dirs(&self) -> &[String] {
        &self.r_dirs
    }

    /// Write-directory allow-list as stored.
    pub fn w_dirs(&self) -> &[String] {
        &self.w_dirs
    }

    /// Read-file available-files as stored (including `w` files).
    pub fn r_files(&self) -> &[String] {
        &self.r_files
    }

    /// Write-file available-files as stored.
    pub fn w_files(&self) -> &[String] {
        &self.w_files
    }

    /// Allowed extensions. Empty = any.
    pub fn extensions(&self) -> &[String] {
        &self.extensions
    }

    /// Check directory/file access for `r` or `w`.
    pub fn check_access(&self, path: &str, mode: char) -> Result<(), String> {
        if self.is_deprecated(path) {
            return Err(format!(
                "{mode}-access denied to {path} → path is deprecated (excluded by 'deprecated-dirs'/'deprecated-files' in tools.fs; do not use it)"
            ));
        }
        let (dirs, files) = if mode == 'w' {
            (&self.w_dirs, &self.w_files)
        } else {
            (&self.r_dirs, &self.r_files)
        };
        if self.is_allowed(path, dirs, files) {
            Ok(())
        } else {
            Err(format!(
                "{mode}-access denied to {path} → unavailable file location (list of available directories for {mode}-access is {dirs:?}; list of available files for {mode}-access is {files:?})"
            ))
        }
    }

    /// Check directory/file access with a custom error message.
    pub fn check_access_msg(&self, path: &str, mode: char, error: &str) -> Result<(), String> {
        self.check_access(path, mode).map_err(|_| error.to_string())
    }

    /// Check file extension against the allow-list.
    pub fn check_extensions(&self, path: &str, mode: char) -> Result<(), String> {
        if self.extensions.is_empty() {
            return Ok(());
        }
        let ext = Path::new(path)
            .extension()
            .and_then(|s| s.to_str())
            .map(|s| format!(".{s}"))
            .unwrap_or_default();
        if self.extensions.iter().any(|e| e == &ext) {
            Ok(())
        } else {
            Err(format!(
                "{mode}-access denied to {path} → unavailable file extension {ext} (list of available extensions is {:?})",
                self.extensions
            ))
        }
    }

    /// Grant runtime access. Existing directory → prefix list; otherwise available-files.
    /// `w` also adds the path to the matching `r` list.
    /// Deprecated paths are refused and not added to the allow-list.
    pub fn grant_path_access(&mut self, path: &str, mode: char) -> Result<(), String> {
        if self.is_deprecated(path) {
            return Err(format!(
                "{mode}-access denied to '{path}': path is deprecated"
            ));
        }
        let is_dir = Path::new(path).is_dir();
        let r_list = if is_dir {
            &mut self.r_dirs
        } else {
            &mut self.r_files
        };
        if !r_list.iter().any(|p| p == path) {
            r_list.push(path.to_string());
        }
        if mode == 'w' {
            let w_list = if is_dir {
                &mut self.w_dirs
            } else {
                &mut self.w_files
            };
            if !w_list.iter().any(|p| p == path) {
                w_list.push(path.to_string());
            }
        }
        Ok(())
    }

    /// `true` when `path` is a deprecated file or lies inside a deprecated directory.
    pub fn is_deprecated(&self, path: &str) -> bool {
        let path_parts = comparable_parts(&abspath(path));
        if self
            .deprecated_files
            .iter()
            .any(|f| comparable_parts(&abspath(f)) == path_parts)
        {
            return true;
        }
        self.deprecated_dirs.iter().any(|d| {
            let dir_parts = comparable_parts(&abspath(d));
            !dir_parts.is_empty() && path_parts.starts_with(&dir_parts)
        })
    }

    fn is_allowed(&self, path: &str, dirs: &[String], files: &[String]) -> bool {
        let abs_p = abspath(path);
        let abs_p_s = path_to_string(&abs_p);
        dirs.iter()
            .any(|d| abs_p_s.starts_with(&path_to_string(&abspath(d))))
            || files.iter().any(|f| abs_p_s == path_to_string(&abspath(f)))
    }
}

fn split_prefixed(entries: &[String], r_list: &mut Vec<String>, w_list: &mut Vec<String>) {
    for entry in entries {
        if let Some(rest) = entry.strip_prefix("w:") {
            w_list.push(rest.to_string());
            r_list.push(rest.to_string());
        } else if let Some(rest) = entry.strip_prefix("r:") {
            r_list.push(rest.to_string());
        }
    }
}

/// Python `os.path.abspath` analogue: join with process cwd, normalize `.` / `..`.
pub fn abspath(path: &str) -> PathBuf {
    let path = Path::new(path);
    let joined = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(path)
    };
    let mut out = PathBuf::new();
    for c in joined.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

fn path_to_string(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

fn comparable_parts(path: &Path) -> Vec<String> {
    path.components()
        .map(|c| {
            let s = c.as_os_str().to_string_lossy().replace('\\', "/");
            if cfg!(windows) {
                s.to_lowercase()
            } else {
                s
            }
        })
        .collect()
}

//! Agent loop: session folder, limit checks, iteration, dump.
//!
//! Behaviour matches Python `tools/harness/agent_loop.py`: increment iteration,
//! log the header, enforce token / USD / iteration limits, call `agent.iteration`,
//! dump, stop or continue. `--dump` restores state into a **new** log folder.

use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Instant;

use chrono::Local;
use conf::{AgentKind, Settings};
use logger::{DoubleLogger, Logger};
use tools::{ToolRegistry, ToolsContext};

use crate::agents::{
    format_real_cost, format_usd, Agent, AlibabaAgent, ClaudeAgent, DeepSeekAgent, GoogleAgent,
    XaiAgent,
};

/// Drive one harness session.
pub struct AgentLoop {
    safe_mode: bool,
    logger: Arc<dyn Logger>,
    iteration: i64,
    iteration_limit: i64,
    agent: Box<dyn Agent>,
    agent_config: PathBuf,
    dump_settings: serde_json::Value,
}

impl AgentLoop {
    /// Create logger, tool registry and the vendor agent.
    pub fn new(settings: &Settings, log_file: &Path, temp_dir: PathBuf) -> Result<Self, String> {
        let logger: Arc<dyn Logger> =
            Arc::new(DoubleLogger::new(log_file).map_err(|e| format!("cannot open log: {e}"))?);
        let registry = Arc::new(ToolRegistry::build(
            &settings.tools,
            ToolsContext {
                cwd: settings.cwd.clone(),
                temp_dir,
                logger: logger.clone(),
            },
        ));
        let agent: Box<dyn Agent> = match &settings.agent.kind {
            AgentKind::Xai { .. } => {
                Box::new(XaiAgent::new(registry, logger.clone(), &settings.agent)?)
            }
            AgentKind::Google { .. } => {
                Box::new(GoogleAgent::new(registry, logger.clone(), &settings.agent)?)
            }
            AgentKind::Claude { .. } => {
                Box::new(ClaudeAgent::new(registry, logger.clone(), &settings.agent)?)
            }
            AgentKind::DeepSeek { .. } => Box::new(DeepSeekAgent::new(
                registry,
                logger.clone(),
                &settings.agent,
            )?),
            AgentKind::Alibaba { .. } => Box::new(AlibabaAgent::new(
                registry,
                logger.clone(),
                &settings.agent,
            )?),
        };
        Ok(Self {
            safe_mode: settings.agent.mode.is_safe(),
            logger,
            iteration: 0,
            iteration_limit: settings.agent.iteration_limit,
            agent,
            agent_config: settings.agent.config_path.clone(),
            dump_settings: settings.source.clone(),
        })
    }

    /// Run the loop. `source_dump` restores history; a new dump is still written to `dump_file`.
    pub fn start(
        &mut self,
        mut prompt: Option<String>,
        dump_file: &Path,
        source_dump: Option<&Path>,
    ) -> Result<(), String> {
        if let Some(src) = source_dump {
            self.agent.reload_session(src)?;
            prompt = None;
        }
        self.logger.log_line("# Agent-loop session:");
        self.logger.log_line(&format!(
            "- agent: {} {}",
            self.agent.vendor(),
            self.agent.model()
        ));
        self.logger
            .log_line(&format!("- agent config: {}", self.agent_config.display()));
        self.logger
            .log_line(&format!("- iteration limit: {}", self.iteration_limit));
        self.logger
            .log_line(&format!("- tokens limit: {}", self.agent.tokens_limit()));
        self.logger
            .log_line(&format!("- usd limit: {}", self.agent.limit_usd()));
        self.logger.log_line(&format!(
            "- start time: {}",
            Local::now().format("%Y-%m-%d %H:%M")
        ));
        if let Some(src) = source_dump {
            self.logger
                .log_line(&format!("- continue from dump: {}", src.display()));
            self.logger.log_line("- settings: from dump");
        }
        self.logger.log_line("");
        self.logger.log_line("# Iterations:");

        let start_time = Instant::now();
        loop {
            self.iteration += 1;
            let elapsed = start_time.elapsed().as_secs();
            self.logger.log_line("");
            self.logger.log_line(&iteration_header(
                self.iteration,
                elapsed,
                self.agent.consumed_tokens(),
                self.agent.consumed_usd(),
                self.agent.consumed_usd_real(),
            ));

            if !self.check_limit(
                "tokens",
                self.agent.tokens_limit() as f64,
                self.agent.consumed_tokens() as f64,
            ) {
                return Err("interrupt loop: token limit exceed".into());
            }
            if !self.check_limit("USD", self.agent.limit_usd(), self.agent.consumed_usd()) {
                return Err("interrupt loop: USD limit exceed".into());
            }
            if !self.check_limit(
                "iteration",
                self.iteration_limit as f64,
                self.iteration as f64,
            ) {
                return Err("interrupt loop: iteration limit exceed".into());
            }

            let stop = self.agent.iteration(prompt.as_deref())?;
            self.agent.dump_session(dump_file)?;
            crate::dump_settings::embed(dump_file, &self.dump_settings)?;
            if stop {
                self.logger.log_line("# Session results:");
                self.agent.finish();
                break;
            }
            prompt = None;
        }
        let secs = start_time.elapsed().as_secs();
        let formatted = format!("{}:{:02}:{:02}", secs / 3600, (secs % 3600) / 60, secs % 60);
        self.logger
            .log_line(&format!("- Execution time: {formatted}"));
        self.logger.log_line("");
        Ok(())
    }

    fn check_limit(&self, kind: &str, limit: f64, consumed: f64) -> bool {
        if (limit - -1.0).abs() > f64::EPSILON && consumed > limit {
            let message = format!("⚠️ {kind} limit exceed ({consumed} > {limit})");
            self.logger.log_line(&message);
            if self.safe_mode {
                return confirm(&format!("{message} → resume execution? [y/N]: "));
            }
        }
        true
    }
}

/// Build the iteration header block logged before each model call.
fn iteration_header(
    iteration: i64,
    elapsed_secs: u64,
    tokens: i64,
    usd: f64,
    real_usd: Option<f64>,
) -> String {
    format!(
        "## Iteration №{}\nUsage:\n- time = {}\n- tokens = {}\n- USD approximated = {}\n- USD real = {}",
        iteration,
        format_elapsed(elapsed_secs),
        tokens,
        format_usd(usd),
        format_real_cost(real_usd)
    )
}

fn format_elapsed(secs: u64) -> String {
    format!("{} min {} sec", secs / 60, secs % 60)
}

fn confirm(prompt: &str) -> bool {
    print!("{prompt}");
    let _ = io::stdout().flush();
    let mut buf = String::new();
    if io::stdin().read_line(&mut buf).is_err() {
        return false;
    }
    matches!(buf.trim().to_lowercase().as_str(), "y" | "yes")
}

/// `{cwd}/{log-folder}/{YYYY-MM-DD HH-MM}_{vendor}_{model}/`
pub fn session_dir(settings: &Settings) -> Result<PathBuf, String> {
    let stamp = Local::now().format("%Y-%m-%d %H-%M");
    let folder = format!(
        "{}_{}_{}",
        stamp, settings.agent.vendor, settings.agent.name
    );
    let dir = settings.cwd.join(&settings.log_folder).join(folder);
    std::fs::create_dir_all(&dir).map_err(|e| format!("cannot create log dir: {e}"))?;
    Ok(dir)
}

